    Check(SetParent(w,c,a,&error),error);auto g=Object(w,"g");Check(SetParent(w,g,c,&error),error);auto before=SceneSerializer::CaptureWorld(w);auto matrices=HierarchyGraph::Build(w);auto identity=w.GetIdentity();
