    auto invalid=HierarchyEdit::Capture(w,{a,d});invalid.back().relationship=RelationshipComponent{std::string("missing"),0};Reject(w,[&]{HierarchyEdit::Apply(w,invalid);},"one invalid batch member rejects all");
