    auto nonfinite=HierarchyEdit::Capture(w,{a});nonfinite.front().local.position.x=std::numeric_limits<float>::infinity();Reject(w,[&]{HierarchyEdit::Apply(w,nonfinite);},"nonfinite candidate");
    for(auto scale:std::vector<Vec3>{{-2,2,2},{2,3,4},{1,1,1}}){World t(World::DataMode::HierarchyData);auto x=Object(t,"x"),p=Object(t,"p");t.GetComponent<TransformComponent>(p)->scale=scale;auto m=EvaluateHierarchyMatrix(t,x);auto edits=HierarchyEdit::PrepareReparent(t,{x},p);HierarchyEdit::Apply(t,edits);Check(Near(*m,*EvaluateHierarchyMatrix(t,x)),"negative/nonuniform representable scale preserves full matrix");}
    {World t(World::DataMode::HierarchyData);auto x=Object(t,"x"),p=Object(t,"p");t.GetComponent<TransformComponent>(p)->scale={2,3,4};t.GetComponent<TransformComponent>(x)->rotation={.4f,.3f,.2f};Reject(t,[&]{HierarchyEdit::PrepareReparent(t,{x},p);},"nonrepresentable local shear");t.GetComponent<TransformComponent>(p)->scale={0,1,1};Reject(t,[&]{HierarchyEdit::PrepareReparent(t,{x},p);},"singular parent");t.GetComponent<TransformComponent>(p)->scale={1e-8f,1,1};Reject(t,[&]{HierarchyEdit::PrepareReparent(t,{x},p);},"near singular parent");}
    {World t(World::DataMode::HierarchyData);auto x=Object(t,"x"),p=Object(t,"p"),y=Object(t,"y");t.AddComponent<RigidbodyComponent>(x);auto edits=HierarchyEdit::PrepareReparent(t,{x,y},p);Reject(t,[&]{HierarchyEdit::Apply(t,edits);},"dynamic member rejects entire final graph");}
