    {World t(World::DataMode::HierarchyData);auto x=Object(t,"x"),p=Object(t,"p");t.AddComponent<RelationshipComponent>(p).order=MaximumSiblingOrder;Check(SetParent(t,x,p,&error),error);Reject(t,[&]{HierarchyEdit::PrepareReparent(t,{x},{});},"root sibling order exhausted without renumbering");}
    {World t(World::DataMode::HierarchyData);auto x=Object(t,"x");t.AddComponent<ColliderComponent>(x).autoFitFromMesh=false;auto state=HierarchyEdit::Capture(t,{x});state.front().local.position={2e6f,0,0};Reject(t,[&]{HierarchyEdit::Apply(t,state);},"candidate collider outside physics range");state.front().local.position={0,0,0};state.front().local.scale={0,1,1};Reject(t,[&]{HierarchyEdit::Apply(t,state);},"candidate singular collider");}
