static void History(){
    Application app;std::string error;Check(ApplicationTestAccess::New(app,error),error);auto& w=app.GetWorld();auto& ui=app.GetEditorLayer();
    auto a=Object(w,"a"),b=Object(w,"b"),c=Object(w,"c"),d=Object(w,"d");Check(SetParent(w,c,a,&error),error);
    using Access=editor::EditorHierarchyReparentTestAccess;
    Access::Select(app,a);Access::Select(app,c,true);Access::Select(app,d,true);const auto selection=Access::Selection(app);
    const auto original=SceneSerializer::CaptureWorld(w);const auto identity=w.GetIdentity();
    Check(Access::Move(app,selection.items,b),ui.GetError());auto after=SceneSerializer::CaptureWorld(w);
    Check(ui.UndoCount()==1&&ui.IsSceneDirty()&&Access::Selection(app).items==selection.items&&Access::Selection(app).active==selection.active&&Access::Selection(app).anchor==selection.anchor,"one graph undo record, explicit selection/active/anchor unchanged");
    Check(Access::Move(app,selection.items,b)&&ui.UndoCount()==1,"no-op creates no history");
    for(int i=0;i<4;++i){ui.UndoEdit(app);Check(SceneSerializer::CaptureWorld(w)==original&&ui.UndoCount()==0&&!ui.IsSceneDirty()&&Access::RedoCount(app)==1,"real Undo exact restoration and revision");ui.RedoEdit(app);Check(SceneSerializer::CaptureWorld(w)==after&&ui.UndoCount()==1&&ui.IsSceneDirty()&&Access::RedoCount(app)==0,"real Redo exact restoration");}
    ui.UndoEdit(app);w.AddComponent<RigidbodyComponent>(a);auto redoBlocked=SceneSerializer::CaptureWorld(w);ui.RedoEdit(app);Check(SceneSerializer::CaptureWorld(w)==redoBlocked&&ui.UndoCount()==0&&Access::RedoCount(app)==1&&!ui.GetError().empty(),"Redo failure retains scene and both history stacks");w.RemoveComponent<RigidbodyComponent>(a);ui.RedoEdit(app);Check(SceneSerializer::CaptureWorld(w)==after,"Redo remains usable after refusal");
    Check(!Access::Move(app,selection.items,c)&&SceneSerializer::CaptureWorld(w)==after&&ui.UndoCount()==1&&Access::Selection(app).items==selection.items,"failed graph edit preserves history and selection");
    Check(Access::Move(app,{a,d},{})&&ui.UndoCount()==2,"unparent one transaction");auto unparented=SceneSerializer::CaptureWorld(w);ui.UndoEdit(app);Check(SceneSerializer::CaptureWorld(w)==after,"unparent Undo");ui.RedoEdit(app);Check(SceneSerializer::CaptureWorld(w)==unparented&&w.GetIdentity()==identity,"unparent Redo without World publication");
    // Checked Undo failure keeps both stacks and all scene data untouched.
    w.AddComponent<RigidbodyComponent>(a);auto blocked=SceneSerializer::CaptureWorld(w);auto count=ui.UndoCount();ui.UndoEdit(app);Check(SceneSerializer::CaptureWorld(w)==blocked&&ui.UndoCount()==count&&Access::RedoCount(app)==0&&!ui.GetError().empty(),"Undo rejects now-invalid physics atomically");w.RemoveComponent<RigidbodyComponent>(a);ui.UndoEdit(app);Check(SceneSerializer::CaptureWorld(w)==after,"Undo still works after rejected attempt");
    Check(ApplicationTestAccess::New(app,error),error);auto fresh=SceneSerializer::CaptureWorld(app.GetWorld());ui.UndoEdit(app);Check(ui.UndoCount()==0&&SceneSerializer::CaptureWorld(app.GetWorld())==fresh,"scene publication invalidates graph history");
    auto sun=Object(app.GetWorld(),"sun"),parent=Object(app.GetWorld(),"parent");app.GetWorld().AddComponent<DirectionalLightComponent>(sun);auto settings=app.GetSceneSettings();settings.background.sunSync=SunSyncMode::SkyDrivesLight;settings.background.sunMetadata=true;settings.background.sunDirection={0,1,0};Check(app.SetSceneSettings(settings,&error),error);app.GetWorld().GetComponent<TransformComponent>(parent)->scale={2,3,4};auto prior=SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings());
    Check(!Access::Move(app,{sun},parent)&&SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings())==prior&&ui.UndoCount()==0,"exact A3 sun guard rejects without settings/Transform/history mutation");
}
using Access=editor::EditorHierarchyReparentTestAccess;
static Entity Find(const World& w,const std::string& id){for(auto e:w.Entities())if(SceneSerializer::EntitySceneId(w,e)==id)return e;return {};}
static void Populate(World& w){auto a=Object(w,"a"),c=Object(w,"c"),g=Object(w,"g");Object(w,"d");auto p=Object(w,"target");Object(w,"other");std::string error;Check(SetParent(w,c,a,&error),error);Check(SetParent(w,g,c,&error),error);w.GetComponent<TransformComponent>(p)->position={2,1,0};}
static ImGuiWindow* RowsWindow(){auto* panel=ImGui::FindWindowByName("Hierarchy Tree");Check(panel&&panel->Active,"actual Hierarchy Tree");for(auto* c:panel->DC.ChildWindows)if(c->Active&&std::string(c->Name).find("/Rows_")!=std::string::npos)return c;throw std::runtime_error("missing Rows");}
static ImVec2 Point(Application& app,const std::string& id,bool arrow=false){auto* rows=RowsWindow();const auto& list=Access::Rows(app);auto it=std::find_if(list.begin(),list.end(),[&](auto& r){return SceneSerializer::EntitySceneId(app.GetWorld(),r.entity)==id;});std::string visible;for(auto& r:list)visible+=SceneSerializer::EntitySceneId(app.GetWorld(),r.entity)+",";Check(it!=list.end(),"visible source/target "+id+"; visible="+visible+" undo="+std::to_string(app.GetEditorLayer().UndoCount()));const auto indent=std::min(float(it->depth)*ImGui::GetStyle().IndentSpacing,rows->WorkRect.GetWidth()*.45f);return {rows->WorkRect.Min.x+indent+ImGui::GetFontSize()*(arrow?.5f:2.5f),rows->DC.CursorStartPos.y+float(it-list.begin())*ImGui::GetFrameHeightWithSpacing()+ImGui::GetFrameHeight()*.5f};}
static ImVec2 RootPoint(){auto p=ImGui::FindWindowByName("Hierarchy Tree")->DC.CursorStartPos;return {p.x+60,p.y+ImGui::GetFrameHeightWithSpacing()+ImGui::GetFrameHeight()*.5f};}
template<class F>static void Click(Application& app,F& frame,const std::string& id,bool ctrl=false,bool arrow=false){auto p=Point(app,id,arrow);SyntheticEditorInput::Key(ImGuiMod_Ctrl,ctrl);SyntheticEditorInput::Position(p.x,p.y);frame();SyntheticEditorInput::Button(0,true);frame();SyntheticEditorInput::Button(0,false);frame();SyntheticEditorInput::Key(ImGuiMod_Ctrl,false);frame();}
template<class F>static void Key(F& frame,ImGuiKey key,bool ctrl=false){SyntheticEditorInput::Key(ImGuiMod_Ctrl,ctrl);SyntheticEditorInput::Key(key,true);frame();SyntheticEditorInput::Key(key,false);SyntheticEditorInput::Key(ImGuiMod_Ctrl,false);frame();}
template<class F>static void BeginDrag(Application& app,F& frame,const std::string& id){auto selection=Access::Selection(app);auto p=Point(app,id);SyntheticEditorInput::Position(p.x,p.y);frame();SyntheticEditorInput::Button(0,true);frame();SyntheticEditorInput::Position(p.x+18,p.y+1);frame();Check(ImGui::IsDragDropActive()&&ImGui::GetDragDropPayload()->IsDataType("WHISP_HIERARCHY_ENTITY"),"real ImGui drag source/payload");Check(Access::Selection(app).items==selection.items&&Access::Selection(app).active==selection.active&&Access::Selection(app).anchor==selection.anchor,"drag start never changes selection");}
