    Check(ApplicationTestAccess::Open(app,"Scenes/Tree.json",error),error);frame();Click(app,frame,"a");BeginDrag(app,frame,"a");Drop(frame,Point(app,"target"));frame();Check(app.GetRenderStatistics().submitted.drawCalls>0,"actual scene rendering after native drop");Check(app.SaveSceneAs("Scenes/Reparented.json",false,&error),error);auto disk=SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings());Check(ApplicationTestAccess::Open(app,"Scenes/Reparented.json",error),error);frame();Check(SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings())==disk&&app.GetEditorLayer().UndoCount()==0,"production Save As/Open disk roundtrip after native drop");
    Check(ApplicationTestAccess::Open(app,"Scenes/Tree.json",error),error);frame();Click(app,frame,"a");BeginDrag(app,frame,"a");Drop(frame,Point(app,"target"));auto author=SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings());auto selected=app.GetEditorLayer().GetSelectedEntities();auto count=app.GetEditorLayer().UndoCount();app.SetEditorPlayMode(true);frame();Check(app.IsEditorPlayMode(),"real H Play");auto runtime=SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings());
    auto p=Point(app,"a");SyntheticEditorInput::Position(p.x,p.y);frame();SyntheticEditorInput::Button(0,true);frame();SyntheticEditorInput::Position(p.x+25,p.y+1);frame();Check(!ImGui::IsDragDropActive(),"Play blocks graph source");Drop(frame,RootPoint());Key(frame,ImGuiKey_Z,true);Check(SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings())==runtime,"runtime graph/history read-only");app.SetEditorPaused(true);frame();Check(!Access::Move(app,{Find(app.GetWorld(),"a")},{})&&SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings())==runtime,"Pause rejects graph service");app.SetEditorPlayMode(false);frame();Check(SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings())==author&&app.GetEditorLayer().UndoCount()==count&&app.GetEditorLayer().GetSelectedEntities()==selected,"Stop restores author history and selection");Key(frame,ImGuiKey_Z,true);Check(!GetParent(app.GetWorld(),Find(app.GetWorld(),"a")).IsValid(),"author graph Undo remains usable after Stop");
    BeginDrag(app,frame,"a");Check(ApplicationTestAccess::Project(app,fixture.b->descriptorPath,error),error);frame();Drop(frame,RootPoint());Check(app.GetEditorLayer().UndoCount()==0&&!GetParent(app.GetWorld(),Find(app.GetWorld(),"a")).IsValid(),"project publication invalidates pending drag with identical stable IDs");
    Check(app.CloseProject(Application::ProjectDecision::Discard,&error),error);frame();Check(app.OpenLegacyWorkspace(&error),error);frame();Check(!app.GetWorld().IsHierarchyData()&&ImGui::FindWindowByName("Scene Hierarchy")->Active,"Legacy RootOnly editor preserved");Check(dynamic_cast<Dx12RenderAdapter*>(app.GetRenderAdapter())->GetValidationErrorCount()==0,"DX12 validation errors zero");app.Shutdown();
